func formatPanelAssetSize(bytes int) string {
	if bytes < 1024 {
		return fmt.Sprintf("%d B", bytes)
	}
	return fmt.Sprintf("%.1f KB", float64(bytes)/1024)
}

func getPrimaryColorOrDefault(color string) string {
	if color == "" {
		return "#8040BF"
	}
	return color
}

func getSecondaryColorOrDefault(color string) string {
	if color == "" {
		return "#8040BF"
	}
	return color
}

func getFontStyle(font string) string {
	if font == "" {
		return ""
	}
	return "font-family: '" + font + "', ui-sans-serif, system-ui, sans-serif;"
}

